console.log(`After increment: ${newCount}`); // Output: After increment: 11

newCount = myCounter.increment();
console.log(`After second increment: ${newCount}`); // Output: After second increment: 12

// 3. Check the current value
console.log(`Current count: ${myCounter.getCount()}`); // Output: Current count: 12

// 4. Reset the counter
let resetCount = myCounter.reset();
console.log(`After reset: ${resetCount}`); // Output: After reset: 0

