 * Reads a text file and returns the total number of lines in it.
 *
 * @param {string} filePath The absolute or relative path to the text file.
 * @returns {Promise<number>} A promise that resolves with the number of lines.
 * @throws {Error} Throws an error if the file cannot be read or does not exist.
 */
async function countLinesInFile(filePath: string): Promise<number> {
  try {
    // 1. Read the file content as a string
    const content = await fs.readFile(filePath, { encoding: 'utf8' });

    // 2. Split the content by newline characters.
    // The split method on a string will return an array of lines.
    // We use a regular expression /\r?\n/ to handle both Windows (\r\n) and Unix (\n) line endings.
    const lines = content.split(/\r?\n/);

    // 3. Return the length of the resulting array
    return lines.length;

  } catch (error) {
    // Re-throw the error with a more descriptive message if it's a file system error
    if (error instanceof Error) {
      throw new Error(`Failed to read file at ${filePath}: ${error.message}`);
    }
    throw new Error(`An unknown error occurred while processing file: ${filePath}`);
  }
}

