/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every 'wait' milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to throttle invocations to.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
    let timeout = null;
    let lastArgs = null;
    let lastThis = null;
    let lastCallTime = 0;

    /**
     * The throttled function wrapper.
     * @param {...any} args Arguments passed to the throttled function.
     */
    return function(...args) {
        const context = this;
        const now = Date.now();

        // Check if we are within the waiting period
        if (now - lastCallTime < wait) {
            // If not, store the latest arguments and context
            lastArgs = args;
            lastThis = context;
            // If there's no pending timeout, set one up to execute the function
            if (!timeout) {
                timeout = setTimeout(() => {
                    // Execute the function with the last recorded arguments and context
                    func.apply(lastThis, lastArgs);
                    // Reset the state after execution
                    timeout = null;
                    lastArgs = null;
                    lastThis = null;
                    lastCallTime = Date.now();
                }, wait - (now - lastCallTime)); // Calculate remaining time for better accuracy
            }
            return;
        }

        // If we are outside the waiting period, execute immediately
        lastCallTime = now;
        func.apply(context, args);
    };
}

